  private extractTLSConfig(config: any): ServiceTLSConfig {
    const tls = config.tls || config.ssl || {};
    return {
      enabled: tls.enabled !== false,
      version: tls.version || "TLSv1.2",
      certFile: tls.cert || tls.certFile,
      keyFile: tls.key || tls.keyFile,
      caFile: tls.ca || tls.caFile,
      cipherSuites: tls.ciphers || tls.cipherSuites || [],
      hstsEnabled: tls.hsts !== false,
      hstsMaxAge: tls.hstsMaxAge || 31536000,
      hstsIncludeSubdomains: tls.hstsIncludeSubdomains || false,
      hstsPreload: tls.hstsPreload || false,
    };
